    'assets/images/regions/llamreis-ankunft.png',
    'assets/images/regions/rhonwens-traenen.png',
    'assets/images/regions/rhosmere.png',
    'assets/images/regions/abergwint.png',
    'assets/images/regions/camruisge.png',
