  assert.deepEqual(mainRecord?.folderPath, ['Vennyr', 'Blütenland', 'Baronie Hoyers Krone', 'Lyndor']);
  assert.deepEqual(talgarthRecord?.folderPath, ['Cenyr', 'Klaueninsel', 'Sturmklaue', 'Talgarth']);
