test('bildet Haus Marchog vollständig mit Gründer, Erbfolge und getrennten Affären ab', () => {
  const family = HOUSE_MARCHOG_FAMILY;
  const { diagnostics } = assertValidFamily(family);
  const parentageByChild = new Map(family.parentages.map(parentage => [parentage.childId, parentage]));

  assert.equal(diagnostics.filter(item => item.severity === 'error').length, 0);
  assert.equal(family.document.title, "Haus Marchog O'Glyndraith");
  assert.equal(family.document.houseProfile.rankId, 'knight-prince');
  assert.deepEqual(
    createFolderPathFromHouseProfile(family.document.houseProfile),
    ['Cenyr', 'Ährental', 'Tristams Ebene', 'Glyndraith']
  );
  assert.equal(family.persons.length, 49);
  assert.equal(family.partnerships.length, 20);
  assert.equal(family.parentages.length, 28);
  assert.equal(family.timeJumps.length, 0);
  assert.equal(family.extensions.blankFamily, false);

  const succession = [
    ['breannain-marchog', 'Ritterfürst von Glyndraith · Gründer und Oberhaupt'],
    ['rhodrhi-marchog', 'Erster Erbe des Hauses Marchog'],
    ['hevedydd-marchog', 'Zweiter Erbe des Hauses Marchog'],
    ['llyonell-marchog', 'Dritter Erbe des Hauses Marchog'],
    ['brizio-marchog', 'Vierter Erbe des Hauses Marchog'],
    ['caraf-marchog', 'Fünfter Erbe des Hauses Marchog']
  ];
  succession.forEach(([personId, title]) => {
    assert.equal(family.persons.find(person => person.id === personId)?.title, title, personId);
  });

  assert.equal(parentageByChild.get('yvain-marchog')?.partnershipId, 'marriage-breannain-delwen');
  assert.equal(parentageByChild.get('rhodrhi-marchog')?.partnershipId, 'marriage-breannain-delwen');
  assert.equal(parentageByChild.get('owain-marchog')?.partnershipId, 'marriage-breannain-arianwen');
  assert.equal(parentageByChild.get('jennalyn-marchog')?.partnershipId, 'marriage-breannain-arianwen');
  assert.equal(parentageByChild.get('enora-marchog')?.partnershipId, 'affair-breannain-mari');
  assert.equal(parentageByChild.get('evain-marchog')?.partnershipId, 'affair-breannain-mabli');
  assert.equal(parentageByChild.get('enora-marchog')?.legitimacy, 'illegitimate');
  assert.equal(parentageByChild.get('evain-marchog')?.legitimacy, 'illegitimate');
  assert.equal(
    family.persons.find(person => person.id === 'mari-marchog-affair')?.title,
    'Affäre Bréannains · Mutter von Enora Marchog'
  );
  assert.equal(
    family.persons.find(person => person.id === 'mabli-marchog-affair')?.title,
    'Affäre Bréannains · Mutter von Evain Marchog'
  );
  assert.equal(
    family.persons.find(person => person.id === 'enora-marchog')?.title,
    'Bastardkind von Bréannain & Mari'
  );
  assert.equal(
    family.persons.find(person => person.id === 'evain-marchog')?.title,
    'Bastardkind von Bréannain & Mabli'
  );
  assert.deepEqual(
    family.partnerships.filter(partnership => partnership.type === 'affair').map(partnership => partnership.id).sort(),
    ['affair-breannain-mabli', 'affair-breannain-mari']
  );
});

test('ordnet Marchogs Hausknoten und sämtliche Fortsetzungen ohne Doppelpersonen an', () => {
  const family = HOUSE_MARCHOG_FAMILY;
  const converted = toFamilyChartData(family);
  const chartById = new Map(converted.data.map(node => [node.id, node]));
  const crest = chartById.get('__lineage-crest-haus-marchog');
  const { reachableNodeIds } = collectReachableChartNodeIds(family);

  assert.equal(converted.diagnostics.filter(item => item.severity === 'error').length, 0);
  assert.deepEqual(crest.rels.parents, ['unknown-father-marchog', 'unknown-mother-marchog']);
  assert.deepEqual(crest.rels.children, ['breannain-marchog']);
  assert.equal(new Set(converted.data.map(node => node.id)).size, converted.data.length);
  family.persons.forEach(person => assert.ok(reachableNodeIds.has(person.id), `${person.id}: nicht erreichbar`));
  assert.equal(
    converted.data.filter(node => node.data.aleria.personId === 'breannain-marchog').length,
    1,
    'Bréannain darf für seine weiteren Beziehungen nicht gedoppelt werden.'
  );

  const shiftedMaternalBranches = [
    ['marriage-breannain-delwen', 'delwen', ['yvain-marchog', 'rhodrhi-marchog']],
    ['marriage-breannain-arianwen', 'arianwen', ['owain-marchog', 'jennalyn-marchog']],
    ['affair-breannain-mari', 'mari-marchog-affair', ['enora-marchog']],
    ['affair-breannain-mabli', 'mabli-marchog-affair', ['evain-marchog']]
  ];
  shiftedMaternalBranches.forEach(([partnershipId, motherId, childIds]) => {
    const partnership = family.partnerships.find(item => item.id === partnershipId);
    assert.equal(partnership.extensions.chartAlignPartnerOverChildrenPersonId, motherId, partnershipId);
    assert.ok(chartById.get('breannain-marchog').rels.spouses.includes(motherId), partnershipId);
    childIds.forEach(childId => {
      assert.deepEqual(
        [...chartById.get(childId).rels.parents].sort(),
        ['breannain-marchog', motherId].sort(),
        `${partnershipId}: Die fachliche Abstammung bleibt vollständig`
      );
    });
  });

  const alignmentPlan = createFamilyChartPartnerAlignmentPlan(family);
  assert.deepEqual(
    alignmentPlan.partnerOverChildrenRoutes.map(route => route.partnerPersonId),
    ['delwen', 'arianwen', 'mari-marchog-affair', 'mabli-marchog-affair']
  );
  assert.deepEqual(alignmentPlan.centerBetweenSpousesRoutes, [{
    centeredPersonId: 'breannain-marchog',
    spousePersonIds: ['delwen', 'arianwen'],
    partnershipIds: ['marriage-breannain-delwen', 'marriage-breannain-arianwen']
  }]);
  assert.deepEqual(alignmentPlan.lineageOriginRoute, {
    targetPersonId: 'breannain-marchog',
    anchorNodeId: '__lineage-crest-haus-marchog',
    originNodeIds: [
      'unknown-father-marchog',
      'unknown-mother-marchog',
      '__lineage-crest-haus-marchog'
    ]
  });
  assert.equal(alignmentPlan.invalidRequests.length, 0);
  const mockTree = {
    data: [
      { data: { id: 'breannain-marchog' }, x: 0, sx: 0 },
      { data: { id: 'delwen' }, spouse: {}, x: 50, sx: 50 },
      { data: { id: 'yvain-marchog' }, x: 100 },
      { data: { id: 'rhodrhi-marchog' }, x: 300 },
      { data: { id: 'arianwen' }, spouse: {}, x: 100, sx: 100 },
      { data: { id: 'owain-marchog' }, x: 500 },
      { data: { id: 'jennalyn-marchog' }, x: 700 },
      { data: { id: 'mari-marchog-affair' }, spouse: {}, x: 200, sx: 200 },
      { data: { id: 'enora-marchog' }, x: 900 },
      { data: { id: 'mabli-marchog-affair' }, spouse: {}, x: 300, sx: 300 },
      { data: { id: 'evain-marchog' }, x: 1100 },
      { data: { id: 'unknown-father-marchog' }, x: 600, sx: 600 },
      { data: { id: 'unknown-mother-marchog' }, spouse: {}, x: 800, sx: 700 },
      { data: { id: '__lineage-crest-haus-marchog' }, x: 700, sx: 700 }
    ]
  };
  const appliedAlignments = applyFamilyChartPartnerAlignmentPlan({ tree: mockTree, plan: alignmentPlan });
  const mockTreeById = new Map(mockTree.data.map(node => [node.data.id, node]));
  assert.equal(appliedAlignments.partnerOverChildren.length, 4);
  assert.equal(appliedAlignments.centeredPeople.length, 1);
  assert.equal(mockTree.data[1].x, 200, 'Delwen steht mittig über beiden Kindern ihrer Ehe.');
  assert.equal(mockTree.data[4].x, 600, 'Arianwen steht mittig über beiden Kindern ihrer Ehe.');
  assert.equal(mockTree.data[4].sx, 600, 'Arianwens Kinderlinie beginnt mittig unter ihrer Karte.');
  assert.equal(mockTree.data[7].x, 900, 'Mari steht direkt über Enora.');
  assert.equal(mockTree.data[9].x, 1100, 'Mabli steht direkt über Evain.');
  assert.equal(mockTree.data[0].x, 400, 'Bréannain steht mittig zwischen seinen beiden legitimen Ehefrauen.');
  assert.equal(mockTree.data[0].sx, 400, 'Bréannains gemeinsame Nachkommenlinie folgt seiner zentrierten Karte.');
  assert.equal(appliedAlignments.alignedLineageOrigin.targetCoordinate, 400);
  assert.equal(mockTreeById.get('__lineage-crest-haus-marchog').x, 400, 'Das Marchog-Wappen steht direkt über Bréannain.');
  assert.equal(mockTreeById.get('__lineage-crest-haus-marchog').sx, 400, 'Die Linie vom Wappen geht gerade nach unten.');
  assert.equal(mockTreeById.get('unknown-father-marchog').x, 300);
  assert.equal(mockTreeById.get('unknown-mother-marchog').x, 500);
  assert.equal(mockTreeById.get('unknown-mother-marchog').sx, 400, 'Das Gründerpaar bleibt über dem Wappen zentriert.');

  const youngestIds = family.persons
    .filter(person => /^17(?:1[8-9]|2\d|3\d)$/.test(person.birth))
    .map(person => person.id);
  const partneredIds = new Set(family.partnerships.flatMap(partnership => partnership.participantIds));
  youngestIds.forEach(personId => assert.equal(partneredIds.has(personId), false, `${personId}: junge Generation bleibt ledig`));
});

test('zentriert eine gemeinsame Person optional nur zwischen ausdrücklich gewählten Ehepartnern', () => {
  const family = {
    persons: [
      {
        id: 'shared-parent',
        extensions: { chartCenterBetweenSpousePersonIds: ['first-spouse', 'second-spouse'] }
      },
      { id: 'first-spouse', extensions: {} },
      { id: 'second-spouse', extensions: {} },
      { id: 'affair-partner', extensions: {} }
    ],
    partnerships: [
      { id: 'first-marriage', type: 'marriage', participantIds: ['shared-parent', 'first-spouse'], extensions: {} },
      { id: 'second-marriage', type: 'marriage', participantIds: ['shared-parent', 'second-spouse'], extensions: {} },
      { id: 'affair', type: 'affair', participantIds: ['shared-parent', 'affair-partner'], extensions: {} }
    ],
    parentages: []
  };
  const plan = createFamilyChartPartnerAlignmentPlan(family);

  assert.deepEqual(plan.centerBetweenSpousesRoutes, [{
    centeredPersonId: 'shared-parent',
    spousePersonIds: ['first-spouse', 'second-spouse'],
    partnershipIds: ['first-marriage', 'second-marriage']
  }]);
  assert.equal(plan.invalidRequests.length, 0);

  const tree = {
    data: [
      { data: { id: 'shared-parent' }, y: 0, sx: 0 },
      { data: { id: 'first-spouse' }, spouse: {}, y: 200, sx: 200 },
      { data: { id: 'second-spouse' }, spouse: {}, y: 600, sx: 600 },
      { data: { id: 'affair-partner' }, spouse: {}, y: 1200, sx: 1200 }
    ]
  };
  applyFamilyChartPartnerAlignmentPlan({ tree, plan, orientation: 'horizontal' });
  assert.equal(tree.data[0].y, 400);
  assert.equal(tree.data[0].sx, 400);

  const invalidFamily = structuredClone(family);
  invalidFamily.persons[0].extensions.chartCenterBetweenSpousePersonIds = ['first-spouse', 'affair-partner'];
  const invalidPlan = createFamilyChartPartnerAlignmentPlan(invalidFamily);
  assert.equal(invalidPlan.centerBetweenSpousesRoutes.length, 0);
  assert.deepEqual(invalidPlan.invalidRequests, [{
    kind: 'center-between-spouses',
    centeredPersonId: 'shared-parent',
    spousePersonIds: ['first-spouse', 'affair-partner'],
    invalidSpousePersonIds: ['affair-partner']
  }]);

  const defaultFamily = structuredClone(family);
  defaultFamily.persons[0].extensions = {};
  assert.equal(
    createFamilyChartPartnerAlignmentPlan(defaultFamily).centerBetweenSpousesRoutes.length,
    0,
    'Ohne Opt-in bleibt die normale Family-Chart-Anordnung unverändert.'
  );
});

test('packt Ehe, Kernperson und kleinen Affärenzweig ohne fremde Karten dazwischen', () => {
  const family = {
    persons: [
      {
        id: 'shared-parent',
        extensions: { chartCenterBetweenPartnerPersonIds: ['wife', 'affair-partner'] }
      },
      { id: 'wife', extensions: {} },
      { id: 'affair-partner', extensions: {} },
      { id: 'legitimate-child', extensions: {} },
      { id: 'child-spouse', extensions: {} },
      { id: 'grandchild', extensions: {} },
      { id: 'bastard', extensions: {} },
      { id: 'unrelated-sibling', extensions: {} }
    ],
    partnerships: [
      {
        id: 'marriage',
        type: 'marriage',
        participantIds: ['shared-parent', 'wife'],
        extensions: {
          chartAlignPartnerOverChildrenPersonId: 'wife'
        }
      },
      {
        id: 'affair',
        type: 'affair',
        participantIds: ['shared-parent', 'affair-partner'],
        extensions: {
          chartAlignPartnerOverChildrenPersonId: 'affair-partner',
          chartReserveLeafChildLane: true
        }
      },
      {
        id: 'child-marriage',
        type: 'marriage',
        participantIds: ['legitimate-child', 'child-spouse'],
        extensions: {}
      }
    ],
    parentages: [
      {
        id: 'legitimate-parentage',
        childId: 'legitimate-child',
        parentIds: ['shared-parent', 'wife'],
        partnershipId: 'marriage'
      },
      {
        id: 'grandchild-parentage',
        childId: 'grandchild',
        parentIds: ['legitimate-child', 'child-spouse'],
        partnershipId: 'child-marriage'
      },
      {
        id: 'bastard-parentage',
        childId: 'bastard',
        parentIds: ['shared-parent', 'affair-partner'],
        partnershipId: 'affair'
      }
    ]
  };
  const plan = createFamilyChartPartnerAlignmentPlan(family);
  const tree = {
    data: [
      { data: { id: 'shared-parent' }, x: 1408, y: 0, sx: 1408 },
      { data: { id: 'wife' }, spouse: {}, x: 0, y: 0, sx: 0 },
      { data: { id: 'affair-partner' }, spouse: {}, x: 704, y: 0, sx: 704 },
      { data: { id: 'legitimate-child' }, x: 0, y: 250, sx: 0 },
      { data: { id: 'child-spouse' }, spouse: {}, x: 352, y: 250, sx: 352 },
      { data: { id: 'grandchild' }, x: 0, y: 500, sx: 0 },
      { data: { id: 'bastard' }, x: 704, y: 250, sx: 704 },
      { data: { id: 'unrelated-sibling' }, x: 1056, y: 0, sx: 1056 }
    ]
  };

  const applied = applyFamilyChartPartnerAlignmentPlan({ tree, plan });
  const nodeById = new Map(tree.data.map(node => [node.data.id, node]));

  assert.equal(plan.invalidRequests.length, 0);
  assert.deepEqual(plan.centerBetweenPartnersRoutes, [{
    centeredPersonId: 'shared-parent',
    partnerPersonIds: ['wife', 'affair-partner'],
    partnershipIds: ['marriage', 'affair']
  }]);
  assert.equal(nodeById.get('shared-parent').x, 352, 'Nur die gemeinsame Kernperson rückt zwischen die Partnerkarten.');
  assert.equal(nodeById.get('wife').x, 0, 'Die Ehefrau bleibt über ihrem lokalen Kinderzweig.');
  assert.equal(nodeById.get('legitimate-child').x, 0);
  assert.equal(nodeById.get('grandchild').x, 0);
  assert.equal(nodeById.get('child-spouse').x, 352, 'Der fortgeführte Nachkommenszweig wird nicht übers Diagramm verschoben.');
  assert.equal(nodeById.get('unrelated-sibling').x, 1056, 'Eine fremde Geschwisterkarte bleibt unangetastet.');
  assert.equal(nodeById.get('affair-partner').x, 704, 'Die Affäre bleibt über ihrem eigenen Bastard.');
  assert.equal(nodeById.get('bastard').x, 704);
  assert.deepEqual(applied.collisionResolutions, []);
  assert.equal(applied.centeredPeople[0].strategy, 'pack-centered-leaf-partner-lane');
  assert.equal(
    nodeById.get('wife').x + 320 < nodeById.get('shared-parent').x,
    true,
    'Zwischen Ehefrau und Kernperson bleibt ein sichtbarer Kartenabstand.'
  );
  assert.equal(
    nodeById.get('shared-parent').x + 320 < nodeById.get('affair-partner').x,
    true,
    'Zwischen Kernperson und Affäre darf keine fremde Karte liegen.'
  );
});

test('haelt eine ausdruecklich kompakte Mehrpartnergruppe samt Mutter-Kind-Spuren lokal zusammen', () => {
  const family = {
    persons: [
      {
        id: 'core',
        extensions: {
          chartCenterBetweenPartnerPersonIds: ['wife', 'affair-partner'],
          chartKeepPartnerGroupTogether: true
        }
      },
      { id: 'wife', extensions: {} },
      { id: 'affair-partner', extensions: {} },
      { id: 'first-legitimate-child', extensions: {} },
      { id: 'second-legitimate-child', extensions: {} },
      { id: 'bastard-child', extensions: {} },
      { id: 'unrelated-sibling', extensions: {} }
    ],
    partnerships: [
      {
        id: 'marriage',
        type: 'marriage',
        participantIds: ['core', 'wife'],
        extensions: {
          chartAlignPartnerOverChildrenPersonId: 'wife',
          chartReserveLeafChildLane: true,
          chartArrangeLeafChildrenEvenly: true
        }
      },
      {
        id: 'affair',
        type: 'affair',
        participantIds: ['core', 'affair-partner'],
        extensions: {
          chartAlignPartnerOverChildrenPersonId: 'affair-partner',
          chartReserveLeafChildLane: true
        }
      }
    ],
    parentages: [
      {
        id: 'parentage-first-legitimate-child',
        childId: 'first-legitimate-child',
        parentIds: ['core', 'wife'],
        partnershipId: 'marriage'
      },
      {
        id: 'parentage-second-legitimate-child',
        childId: 'second-legitimate-child',
        parentIds: ['core', 'wife'],
        partnershipId: 'marriage'
      },
      {
        id: 'parentage-bastard-child',
        childId: 'bastard-child',
        parentIds: ['core', 'affair-partner'],
        partnershipId: 'affair'
      }
    ]
  };
  const tree = {
    data: [
      { data: { id: 'core' }, x: 1408, y: 0, sx: 1408 },
      { data: { id: 'wife' }, spouse: {}, x: 0, y: 0, sx: 0 },
      { data: { id: 'affair-partner' }, spouse: {}, x: 1760, y: 0, sx: 1760 },
      { data: { id: 'first-legitimate-child' }, x: 0, y: 250, sx: 0 },
      { data: { id: 'second-legitimate-child' }, x: 352, y: 250, sx: 352 },
      { data: { id: 'bastard-child' }, x: 1760, y: 250, sx: 1760 },
      { data: { id: 'unrelated-sibling' }, x: 704, y: 0, sx: 704 }
    ]
  };

  const plan = createFamilyChartPartnerAlignmentPlan(family);
  const applied = applyFamilyChartPartnerAlignmentPlan({ tree, plan });
  const byId = new Map(tree.data.map(node => [node.data.id, node]));

  assert.equal(plan.centerBetweenPartnersRoutes[0].keepTogether, true);
  assert.equal(byId.get('core').x - byId.get('wife').x, 352);
  assert.equal(byId.get('affair-partner').x - byId.get('core').x, 352);
  assert.equal(
    byId.get('wife').x,
    (byId.get('first-legitimate-child').x + byId.get('second-legitimate-child').x) / 2
  );
  assert.equal(byId.get('affair-partner').x, byId.get('bastard-child').x);
  assert.equal(byId.get('unrelated-sibling').x, 704);
  assert.equal(applied.centeredPeople.some(entry => entry.strategy === 'pack-centered-partner-cards'), true);
});

