function createSyncHarness({
  family,
  storage = createMemoryStorage(),
  remoteRecords = new Map(),
  skipDeploy = true,
  resolveOriginFamily = () => null,
  relatedFamilySource = null
}) {
  const store = createFamilyStore(family);
  const localRepository = createLocalFamilyRepository(storage);
  let authListener = () => {};
  let saveCalls = 0;
  let batchCalls = 0;
  let lastSave = null;
  let lastBatch = null;
  let lastSaveOptions = null;
  const statusElement = { textContent: '' };
  const documentRef = {
    getElementById: id => id === 'save-status' ? statusElement : null,
    addEventListener() {},
    removeEventListener() {}
  };
  const ui = {
    dialog: { addEventListener() {}, removeEventListener() {} },
    form: {},
    render() {},
    open() {},
    close() {},
    showError() {},
    getSaveOptions: () => ({ skipDeploy }),
    readCredentials: () => ({}),
    clearPassword() {}
  };
  const authService = {
    observe(listener) {
      authListener = listener;
      listener(null);
      return () => {};
    },
    async login() {},
    async logout() {}
  };
  const cloudRepository = {
    async loadDraft(familyId) {
      return remoteRecords.get(familyId) || null;
    },
    async saveDraft(record, options) {
      saveCalls += 1;
      lastSave = record;
      lastSaveOptions = options;
      const result = { family: record.family, revision: record.expectedRevision + 1, deploySkipped: options?.skipDeploy === true };
      remoteRecords.set(record.family.document.id, result);
      return result;
    },
    async saveDraftBatch(records, options) {
      batchCalls += 1;
      lastBatch = records;
      lastSaveOptions = options;
      return records.map(record => {
        const result = { family: record.family, revision: record.expectedRevision + 1, deploySkipped: options?.skipDeploy === true };
        remoteRecords.set(record.family.document.id, result);
        return result;
      });
    },
    async watchDraftMetadata() {
      return () => {};
    },
    async publishDraft() {
      return { revision: 1 };
    }
  };
  const controller = createFamilySyncController({
    store,
    localRepository,
    cloudRepository,
    authService,
    documentRef,
    editing: true,
    resolveOriginFamily,
    relatedFamilySource,
    uiFactory: () => ui,
    runtime: { confirm: () => true }
  });
  return {
    controller,
    store,
    storage,
    localRepository,
    signIn(user = { uid: 'test-user', email: 'test@aleria.invalid' }) {
      authListener(user);
    },
    metrics: () => ({ saveCalls, batchCalls, lastSave, lastBatch, lastSaveOptions })
  };
}

